'use client';
import { useEffect, useState } from 'react';

import { cn, omit } from '@/lib';

function svgToElement(element: SVGElement | undefined, data: any) {
  let currentElement;
  if (!element) {
    element = document.createElementNS('http://www.w3.org/2000/svg', data.tagName);
    currentElement = element;
  } else {
    currentElement = document.createElementNS('http://www.w3.org/2000/svg', data.tagName);
    element.appendChild(currentElement);
  }
  for (const attr of Object.keys(omit(data, 'tagName', 'child'))) {
    if (attr.includes(':')) {
      // ...
    } else {
      currentElement.setAttribute(attr, data[attr]);
    }
  }
  if (data.child) {
    for (const child of data.child) {
      svgToElement(currentElement, child);
    }
  }

  return element!;
}

const TourLoadingIcon = ({ className }: PropsWithClassName) => {
  const [currentFrame, setCurrentFrame] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentFrame(p => {
        if (p >= animationFrames.length - 1) {
          return 0;
        }
        return p + 1;
      });
    }, 30);
    return () => {
      clearInterval(interval);
    };
  }, []);

  return (
    <div
      ref={ref => {
        if (ref) {
          ref.innerHTML = '';
          ref.appendChild(svgToElement(undefined, animationFrames[currentFrame]));
        }
      }}
      className={cn("w-[200px] h-[200px] mx-auto mt-[10vh]",className)}/>
  );
};

export default TourLoadingIcon;

